/// Agreements.html template substitution chain (IDA 0x20748..0x2083c):
/// "Terms of Service"/"Licensing Agreement"/"Privacy Policy"/"and" each replaced by the
/// localized word. Like `stringByReplacingOccurrencesOfString:`, every non-overlapping
/// occurrence goes — including "and" inside larger words.
pub fn about_agreement_html(template: &str, bundle: &AboutBundle) -> String {
    template
        .replace("Terms of Service", &bundle.terms_of_service)
        .replace("Licensing Agreement", &bundle.licensing_agreement)
        .replace("Privacy Policy", &bundle.privacy_policy)
        .replace("and", &bundle.and_word)
}

/// Domain label selection (IDA 0x2090e..0x20954): RbxBaseUrl on tablet, RbxBaseMobileUrl otherwise.
pub fn about_domain_name(is_tablet: bool, bundle: &AboutBundle) -> &str {
    if is_tablet { &bundle.base_url } else { &bundle.base_mobile_url }
}

